) : EventChannel.StreamHandler {
  var pigeonSink: PigeonEventSink<T>? = null

  override fun onListen(p0: Any?, sink: EventChannel.EventSink) {
    pigeonSink = PigeonEventSink<T>(sink)
    wrapper.onListen(p0, pigeonSink!!)
  }

  override fun onCancel(p0: Any?) {
    pigeonSink = null
    wrapper.onCancel(p0)
  }
}

interface CameraApiPigeonEventChannelWrapper<T> {
  fun onListen(p0: Any?, sink: PigeonEventSink<T>) {}

  fun onCancel(p0: Any?) {}
}

class PigeonEventSink<T>(private val sink: EventChannel.EventSink) {
  fun success(value: T) {
    sink.success(value)
  }

  fun error(errorCode: String, errorMessage: String?, errorDetails: Any?) {
    sink.error(errorCode, errorMessage, errorDetails)
  }

  fun endOfStream() {
    sink.endOfStream()
  }
}
      
/** A typed channel for communicating with the Flutter application using asynchronous event streams. */
class CornerFramesEventChannel(messenger: BinaryMessenger, instanceName: String = "") {
  private val channel: EventChannel

  init {
    var channelName = "dev.flutter.pigeon.cleanleaf.CameraEventApi.cornerFrames"
    if (instanceName.isNotEmpty()) {
      channelName += ".$instanceName"
    }
    channel = EventChannel(messenger, channelName, CameraApiPigeonMethodCodec)
  }

  /**
   * Sets the stream handler for this channel, replacing any previous handler.
   *
   * Pass `null` to remove the event channel registration.
   */
  fun setStreamHandler(streamHandler: CornerFramesStreamHandler?) {
    val internalHandler = streamHandler?.let { CameraApiPigeonStreamHandler<CornerFrame>(it) }
    channel.setStreamHandler(internalHandler)
  }
}

abstract class CornerFramesStreamHandler : CameraApiPigeonEventChannelWrapper<CornerFrame> {
  companion object {
    /**
     * Creates and returns a new event channel that calls the provided stream handler.
     *
     * The returned channel can be stored to allow changing or removing the stream handler.
     * If the handler will not be changed for the lifetime of the engine associated with the messenger,
     * the return value can be ignored.
     */
    fun register(messenger: BinaryMessenger, streamHandler: CornerFramesStreamHandler, instanceName: String = ""): CornerFramesEventChannel {
      val channel = CornerFramesEventChannel(messenger, instanceName)
      channel.setStreamHandler(streamHandler)
      return channel
    }
  }

  // Implement methods from CameraApiPigeonEventChannelWrapper
  override fun onListen(p0: Any?, sink: PigeonEventSink<CornerFrame>) {}

  override fun onCancel(p0: Any?) {}
}
      
